CREATE TABLE lab_runs (id varchar(80) PRIMARY KEY, policy varchar(16) NOT NULL DEFAULT 'normal', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users (id uuid PRIMARY KEY, run_id varchar(80) NOT NULL REFERENCES lab_runs(id) ON DELETE CASCADE, login_id varchar(120) NOT NULL, password_hash varchar(255) NOT NULL, status varchar(16) NOT NULL DEFAULT 'ACTIVE', auth_version bigint NOT NULL DEFAULT 1, UNIQUE(run_id, login_id));
CREATE TABLE device_auth_grants (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, mode varchar(16) NOT NULL, label varchar(60) NOT NULL, issued_at timestamptz NOT NULL, expires_at timestamptz NOT NULL, auth_version bigint NOT NULL, revoked_at timestamptz);
CREATE INDEX grants_user ON device_auth_grants(user_id);
CREATE TABLE auth_sessions (id uuid PRIMARY KEY, grant_id uuid NOT NULL REFERENCES device_auth_grants(id) ON DELETE CASCADE, sid_hash varchar(64) NOT NULL UNIQUE, state varchar(16) NOT NULL, created_at timestamptz NOT NULL, absolute_expires_at timestamptz NOT NULL, auth_version bigint NOT NULL, preparing_expires_at timestamptz NOT NULL);
CREATE INDEX sessions_grant ON auth_sessions(grant_id);
CREATE TABLE remember_credentials (selector varchar(64) PRIMARY KEY, grant_id uuid NOT NULL UNIQUE REFERENCES device_auth_grants(id) ON DELETE CASCADE, current_hash varchar(64) NOT NULL, previous_hash varchar(64), generation bigint NOT NULL DEFAULT 0, previous_used_at timestamptz, expires_at timestamptz NOT NULL);
CREATE TABLE user_preferences (user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, notifications boolean NOT NULL DEFAULT true, version bigint NOT NULL DEFAULT 1, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE auth_cleanup_tasks (id uuid PRIMARY KEY, session_record_id uuid NOT NULL REFERENCES auth_sessions(id) ON DELETE CASCADE, state varchar(24) NOT NULL DEFAULT 'PENDING', reason varchar(60) NOT NULL, attempts int NOT NULL DEFAULT 0, next_attempt_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE auth_audit_events (id uuid PRIMARY KEY, run_id varchar(80) NOT NULL REFERENCES lab_runs(id) ON DELETE CASCADE, request_id varchar(80) NOT NULL, instance varchar(8) NOT NULL, event varchar(60) NOT NULL, outcome varchar(32) NOT NULL, occurred_at timestamptz NOT NULL DEFAULT now());
